// Helper function to get blog posts by language
export const getBlogPosts = (language: string): BlogPost[] => {
    switch (language) {
        case 'es':
            return blogPostsES;
        case 'fr':
            return blogPostsFR;
        case 'de':
            return blogPostsDE;
        default:
            return blogPostsEN;
    }
};
